import{_ as i,o as s,c as d,a3 as t}from"./chunks/framework.bvEHUNtb.js";const h=JSON.parse('{"title":"传统智慧体系 · 现代解读与传承计划","description":"用现代思维结构，还原、解读、传承中华传统文化的底层智慧体系。","frontmatter":{"title":"传统智慧体系 · 现代解读与传承计划","description":"用现代思维结构，还原、解读、传承中华传统文化的底层智慧体系。","layout":"page","pageClass":"dao-doc-page dao-directory-page traditional-wisdom-directory","aside":false,"outline":false},"headers":[],"relativePath":"topics/traditional-wisdom/index.md","filePath":"topics/traditional-wisdom/index.md","lastUpdated":1786982540000}'),o={name:"topics/traditional-wisdom/index.md"};function n(r,a,e,l,p,c){return s(),d("div",null,[...a[0]||(a[0]=[t('<div class="traditional-wisdom-hero"><p class="traditional-wisdom-hero__eyebrow">现代解读与传承计划</p><h1>传统智慧体系</h1><p>用现代思维结构，还原、解读、传承中华传统文化的底层智慧体系。</p></div><p>这里不是一份玄学工具箱，也不是术数速成手册。它从原典、文字与可考材料出发，尝试理解先人的世界观与方法论，再以现代语言重新表达，让传统智慧能够被今天的人真实地进入、检验与传承。</p><h2 id="整理原则" tabindex="-1">整理原则 <a class="header-anchor" href="#整理原则" aria-label="Permalink to &quot;整理原则&quot;">​</a></h2><div class="traditional-wisdom-principles"><div><strong>正本清源</strong><span>重要论断回到经典出处，区分原文、注疏与个人解读。</span></div><div><strong>如实呈现</strong><span>明确版本差异、历史演变与存疑问题，不把推测写成定论。</span></div><div><strong>还原而非表演</strong><span>先整理文字背后的结构，再讨论它在今天的意义。</span></div><div><strong>面向传承</strong><span>每篇保留出处与脉络，也力求让初学者能够进入。</span></div></div><h2 id="专题结构" tabindex="-1">专题结构 <a class="header-anchor" href="#专题结构" aria-label="Permalink to &quot;专题结构&quot;">​</a></h2><div class="traditional-wisdom-grid"><a href="/topics/traditional-wisdom/cosmology/" class="traditional-wisdom-card"><span class="traditional-wisdom-card__index">一</span><div><h2>哲学底座——宇宙观</h2><p>从道、阴阳、四象、五行进入，建立理解万物关系、变化与秩序的基本框架。</p><span>进入宇宙观</span></div></a><a href="/topics/traditional-wisdom/symbols/" class="traditional-wisdom-card"><span class="traditional-wisdom-card__index">二</span><div><h2>符号系统</h2><p>梳理河图洛书、八卦、六十四卦、星宿与九宫等表述世界的符号与坐标。</p><span>进入符号系统</span></div></a><a href="/topics/traditional-wisdom/time/" class="traditional-wisdom-card"><span class="traditional-wisdom-card__index">三</span><div><h2>时间坐标系</h2><p>以天干地支、六十甲子、节气与历法为线索，理解传统文化如何安放时间与周期。</p><span>进入时间坐标系</span></div></a><a href="/topics/traditional-wisdom/energy/" class="traditional-wisdom-card"><span class="traditional-wisdom-card__index">四</span><div><h2>能量状态系统</h2><p>从十二长生、旺相休囚死、五音十二律，观察生命、时令与关系状态的变化模型。</p><span>进入能量状态系统</span></div></a><a href="/topics/traditional-wisdom/common-knowledge/" class="traditional-wisdom-card"><span class="traditional-wisdom-card__index">C</span><div><h2>通识类</h2><p>收录天文、历法、地理、礼制与哲学概念等阅读原典时高频出现的背景知识。</p><span>进入通识类</span></div></a></div><h2 id="四个维度" tabindex="-1">四个维度 <a class="header-anchor" href="#四个维度" aria-label="Permalink to &quot;四个维度&quot;">​</a></h2><p>这套通识基础也将服务于四条长期阅读线：</p><ul><li><strong>道（Dao）</strong>：哲学与世界观</li><li><strong>术（Shu）</strong>：通识基础与应用系统</li><li><strong>经（Jing）</strong>：经典原典解读</li><li><strong>人（Ren）</strong>：人文、修身与人伦</li></ul><p>它们不是互不相关的栏目，而是一条从世界观、方法论到原典与人的实践的连续路径。</p>',10)])])}const _=i(o,[["render",n]]);export{h as __pageData,_ as default};
